package de.powerradio.studio;
import android.app.*;import android.appwidget.*;import android.content.*;import android.os.*;import android.widget.*;import org.json.*;import java.net.*;import java.io.*;
public class StudioWidget extends AppWidgetProvider {
static String[] stations={"powerradio","powerradio-pop"};
static int[] listeners={R.id.listeners0,R.id.listeners1}, songs={R.id.song0,R.id.song1}, shows={R.id.show0,R.id.show1}, next={R.id.next0,R.id.next1}, counts={R.id.count0,R.id.count1}, plays={R.id.play0,R.id.play1};
static JSONObject get(String s,String path)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL("https://api.laut.fm/station/"+s+path).openConnection();c.setConnectTimeout(4000);c.setReadTimeout(4000);try(InputStream in=c.getInputStream()){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1)b.write(buf,0,n);return new JSONObject(b.toString("UTF-8"));}finally{c.disconnect();}}
@Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){PendingResult pending=goAsync();new Thread(()->{try{RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget);int total=0;boolean known=true;for(int i=0;i<2;i++){Intent a=new Intent(c,MainActivity.class).putExtra("station",i);v.setOnClickPendingIntent(plays[i],PendingIntent.getActivity(c,i,a,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));try{JSONObject j=get(stations[i],"");int l=j.optInt("listeners",-1);if(l<0)known=false;else total+=l;v.setTextViewText(listeners[i],"Hörer: "+(l<0?"—":l));}catch(Exception e){known=false;}try{JSONObject j=get(stations[i],"/current_song");JSONObject artist=j.optJSONObject("artist");v.setTextViewText(songs[i],(artist==null?"":artist.optString("name")+" – ")+j.optString("title","—"));}catch(Exception ignored){}v.setViewVisibility(counts[i],android.view.View.GONE);}v.setTextViewText(R.id.header,"POWER RADIO • "+(known?total+" Hörer":"STUDIO"));m.updateAppWidget(ids,v);}finally{pending.finish();}}).start();}
}